/* Recherche locale dans OFF_MINI_DB — même logique de scoring que
   _searchCiqual (index.html), adaptée avec marque + code-barre.
   _expandSearchTerm est défini dans index.html (portée globale, ce
   fichier est chargé dans le même document). */
function _searchOffMini(query) {
  if (typeof _expandSearchTerm !== 'function' || !Array.isArray(OFF_MINI_DB)) return [];
  const strip = s => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').trim();
  const q = strip(query);
  const tokens = q.split(' ').filter(t => t.length >= 2);
  if (!tokens.length) return [];
  return OFF_MINI_DB
    .map(item => {
      const name = strip(item.n);
      let score = 0, matched = 0;
      tokens.forEach(t => {
        const variants = _expandSearchTerm(t);
        const hit = variants.find(v => name.includes(v));
        if (hit) {
          score += t.length * (hit === t ? 2 : 1.5);
          matched++;
        }
      });
      if (!matched) return null;
      if (name.startsWith(q)) score += 20;
      if (name === q)         score += 30;
      if (matched === tokens.length) score += 10;
      return { item, score };
    })
    .filter(Boolean)
    .sort((a, b) => b.score - a.score)
    .slice(0, 20)
    .map(({ item: x }) => ({
      product_name: x.n, brands: x.b, code: x.c,
      nutriments: {
        'energy-kcal_100g': x.k, 'proteins_100g': x.p,
        'carbohydrates_100g': x.g, 'sugars_100g': x.su,
        'fat_100g': x.l, 'saturated-fat_100g': x.sf,
        'fiber-energy_100g': x.f, 'sodium_100g': x.s / 1000,
      },
      serving_size:'', serving_quantity:null,
      nutriscore_grade:null, image:'',
      _src:'off-mini', _frScore:5,
    }));
}
